import app from 'flarum/forum/app';
import { apiUrl } from './util';
export function request(method, path, options) {
  if (options === void 0) {
    options = {};
  }
  return app.request({
    method,
    url: apiUrl(path),
    params: options.params,
    body: options.body,
    ...(options.raw ? {
      serialize: raw => raw
    } : {})
  });
}

/** The authors that came with a response go into the forum's store, so avatars, names and user cards work. */
export function absorb(response) {
  if (response?.included?.length) app.store.pushPayload({
    data: response.included
  });
  return response;
}
export function user(id) {
  return app.store.getById('users', String(id));
}
let config = null;

/** What the composer and feed need, once per page load. */
export function loadConfig() {
  return config ??= request('GET', '/moments-config').then(r => r.data);
}
export function listMoments(filter, before, limit) {
  if (limit === void 0) {
    limit = 20;
  }
  const params = {
    filter,
    page: {
      limit
    }
  };
  if (before) params.page.before = before;
  return request('GET', '/moments', {
    params
  }).then(absorb);
}
export function getMoment(id) {
  return request('GET', `/moments/${id}`).then(absorb);
}
export function getReplies(id, sort, after) {
  const params = {
    sort
  };
  if (after) params.page = {
    after
  };
  return request('GET', `/moments/${id}/replies`, {
    params
  }).then(absorb);
}
export function saveMoment(body, id) {
  return request(id ? 'PATCH' : 'POST', id ? `/moments/${id}` : '/moments', {
    body
  }).then(absorb);
}
export function deleteMoment(id) {
  return request('DELETE', `/moments/${id}`);
}
export function react(id, reaction) {
  return request(reaction ? 'POST' : 'DELETE', `/moments/${id}/reaction`, reaction ? {
    body: {
      reaction
    }
  } : {}).then(absorb);
}
export function bookmark(id, on) {
  return request(on ? 'POST' : 'DELETE', `/moments/${id}/bookmark`);
}
export function report(id, reason, detail) {
  return request('POST', `/moments/${id}/reports`, {
    body: {
      reason,
      detail
    }
  });
}
export function dismissReports(id) {
  return request('DELETE', `/moments/${id}/reports`);
}
export function newCount(filter, after) {
  return request('GET', '/moments-count', {
    params: {
      filter,
      after
    }
  }).then(r => r.count);
}
export function uploadFile(file, purpose, duration, name) {
  if (name === void 0) {
    name = 'upload';
  }
  const body = new FormData();
  body.append('file', file, name);
  body.append('purpose', purpose);
  if (duration) body.append('duration', String(Math.round(duration)));
  return request('POST', '/moments-media', {
    body,
    raw: true
  }).then(r => r.data);
}

/** With fof/upload: the file goes through it, then is attached by id. */
export function uploadThroughFof(file) {
  const body = new FormData();
  body.append('files[]', file, file.name);
  return app.request({
    method: 'POST',
    url: apiUrl('/fof/upload'),
    body,
    serialize: raw => raw
  }).then(r => {
    const id = Array.isArray(r?.data) ? r.data[0]?.id : r?.data?.id;
    return request('POST', '/moments-media', {
      body: {
        fofFileId: Number(id)
      }
    }).then(res => res.data);
  });
}
export function attachGif(gif) {
  return request('POST', '/moments-media', {
    body: {
      gif
    }
  }).then(r => r.data);
}
export function searchGifs(q, offset) {
  if (offset === void 0) {
    offset = 0;
  }
  return request('GET', '/moments-gifs', {
    params: {
      q,
      offset
    }
  }).then(r => r.data);
}
export function topics(sort, limit) {
  return request('GET', '/moments-topics', {
    params: {
      sort,
      limit
    }
  }).then(r => r.data);
}