import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
import username from 'flarum/common/helpers/username';
import * as api from '../api';
import { t, topicHref } from '../util';
import { loadComposer } from '../composerLoader';
/** What a placed widget shows. Its own lazy chunk, fetched only where a widget is placed. */
export default class WidgetBody extends Component {
  moments = null;
  topics = null;
  config = null;
  Composer = null;
  posted = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (this.attrs.kind === 'latest') {
      api.listMoments({
        feed: 'everyone'
      }, null, this.attrs.limit).then(page => (this.moments = page.data, m.redraw()));
    } else if (this.attrs.kind === 'topics') {
      api.topics('popular', this.attrs.limit).then(topics => (this.topics = topics, m.redraw()));
    } else {
      api.loadConfig().then(config => {
        this.config = config;
        if (config.canPost) loadComposer().then(C => (this.Composer = C, m.redraw()));
        m.redraw();
      });
    }
  }
  view() {
    if (this.attrs.kind === 'compose') return this.compose();
    if (this.attrs.kind === 'topics') return this.topicList();
    if (!this.moments) return m(LoadingIndicator, {
      size: "small"
    });
    if (!this.moments.length) return m("p", {
      className: "MomentsWidget-empty"
    }, t('feed.empty'));
    return m("ul", {
      className: "MomentsWidget MomentsWidget--latest"
    }, this.moments.map(mo => {
      const user = api.user(mo.userId);
      const text = (mo.html ? new DOMParser().parseFromString(mo.html, 'text/html').body.textContent || '' : '').trim();
      return m("li", {
        className: "MomentsWidget-item"
      }, m(Avatar, {
        user: user
      }), m("div", {
        className: "MomentsWidget-text"
      }, m(Link, {
        href: app.route('moments.show', {
          id: mo.id
        }),
        className: "MomentsWidget-link"
      }, m("strong", null, user ? username(user) : ''), " ", m("span", {
        className: "MomentsWidget-time"
      }, humanTime(new Date(mo.createdAt)))), m("span", {
        className: "MomentsWidget-excerpt"
      }, text ? text.slice(0, 120) : mo.media.length ? t('widgets.media') : mo.repostOf ? t('widgets.repost') : '')));
    }), m("li", {
      className: "MomentsWidget-all"
    }, m(Link, {
      href: app.route('moments.index')
    }, t('widgets.all'))));
  }
  topicList() {
    if (!this.topics) return m(LoadingIndicator, {
      size: "small"
    });
    if (!this.topics.length) return m("p", {
      className: "MomentsWidget-empty"
    }, t('widgets.no_topics'));
    return m("ul", {
      className: "MomentsWidget MomentsWidget--topics"
    }, this.topics.map(topic => m("li", null, m(Link, {
      href: topicHref(topic.key),
      className: "MomentsWidget-topic"
    }, m("span", null, "#", topic.name), m("span", {
      className: "MomentsWidget-count"
    }, t('widgets.topic_count', {
      count: topic.count
    }))))));
  }
  compose() {
    if (!this.config) return m(LoadingIndicator, {
      size: "small"
    });
    if (!this.config.canPost) {
      return m("p", {
        className: "MomentsWidget-empty"
      }, m(Link, {
        href: app.route('moments.index')
      }, t('widgets.all')));
    }
    if (this.posted) {
      return m("p", {
        className: "MomentsWidget-done"
      }, t('widgets.posted'), " ", m(Link, {
        href: app.route('moments.index')
      }, t('widgets.all')));
    }
    return this.Composer ? m(this.Composer, {
      config: this.config,
      compact: true,
      onposted: () => this.posted = true
    }) : m(LoadingIndicator, {
      size: "small"
    });
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/components/WidgetBody', WidgetBody);